"""One-time, insert-only-if-missing seed of premium Quest content -- adds a
"Bonus Pack" premium module per age band to each of the 5 original (free)
categories, plus 5 brand-new premium categories. Follows the exact same
insert-if-missing convention as seed.migrate_legacy_learning_content: never
touches a row that already exists (including one an admin has since edited),
so it's safe to call on every startup. All content added here is flagged
is_premium="1" -- the 5 original categories' original modules are never
touched, so every family keeps the same free content they always had.
"""
from sqlalchemy.orm import Session

from helpers import now
from models import DBContentTopic, DBLearningModule

QUEST_SECTION = "quest"
QUEST_AGE_BANDS = [(4, 6), (7, 9), (10, 13), (13, 17)]
BONUS_PACK_POINTS = 16  # 2x the original 8 -- a bigger, premium pack of activities


def _insert_topic_if_missing(db: Session, topic_id: str, title: str, emoji: str, order_index: int) -> None:
    if db.query(DBContentTopic).get(topic_id):
        return
    db.add(DBContentTopic(id=topic_id, section=QUEST_SECTION, title=title, emoji=emoji, order_index=order_index))


def _insert_module_if_missing(db: Session, module_id: str, topic_key: str, topic_title: str, topic_emoji: str,
                               age_min: int, age_max: int, title: str, order_index: int, activities: list) -> None:
    if db.query(DBLearningModule).get(module_id):
        return
    db.add(DBLearningModule(
        id=module_id, section=QUEST_SECTION, section_title="Quests", section_emoji="🧸",
        topic=topic_key, topic_title=topic_title, topic_emoji=topic_emoji,
        age_min=age_min, age_max=age_max, title=title, points=BONUS_PACK_POINTS, order_index=order_index,
        is_active="1", status="published", is_premium="1",
        content={"activities": activities}, created_at=now(),
    ))


