def seed_premium_quest_content(db: Session) -> None:
    order_index = db.query(DBLearningModule).filter(DBLearningModule.section == QUEST_SECTION).count() + 1

    # Bonus packs for the 5 original free categories.
    for category_key, (category_title, category_emoji, bands) in _BONUS_PACKS.items():
        for (age_min, age_max), activities in bands.items():
            module_id = f"{category_key}-{age_min}-{age_max}-premium"
            _insert_module_if_missing(
                db, module_id, category_key, category_title, category_emoji,
                age_min, age_max, f"Ages {age_min}–{age_max} · Bonus Pack", order_index, activities,
            )
            order_index += 1
    db.commit()

    # 5 brand-new premium categories.
    topic_order = db.query(DBContentTopic).filter(DBContentTopic.section == QUEST_SECTION).count() + 1
    for category_key, category_title, category_emoji, bands in _NEW_CATEGORIES:
        _insert_topic_if_missing(db, category_key, category_title, category_emoji, topic_order)
        topic_order += 1
        for (age_min, age_max), activities in bands.items():
            module_id = f"{category_key}-{age_min}-{age_max}"
            _insert_module_if_missing(
                db, module_id, category_key, category_title, category_emoji,
                age_min, age_max, f"Ages {age_min}–{age_max}", order_index, activities,
            )
            order_index += 1
    db.commit()
